  "nok-franke": {"t":"Franke, 'A Chronology of the Central Nigerian Nok Culture: 1500 BC to the Beginning of the Common Era', Journal of African Archaeology 14(3), 2016, open access (search excerpts; not read in full): main phase with terracotta and iron from the 9th to the 4th century BC; the culture ends around the turn of the Common Era; Fagg identified it in 1944; many sites were looted before 2005","s":"Journal of African Archaeology (Brill), Frankfurt Nok project","d":"14/11/2026","u":"https://doi.org/10.3213/2191-5784-10297"},
  "nok-oro": {"t":"The Archaeology of Nok Culture in Nigeria (2nd/1st Millennium BCE), Oxford Research Encyclopedia of African History (search excerpt; not read in full): terracotta from the early 1st millennium BCE; no evidence for social or political complexity; the earliest iron production is at least a century later than the first figurines","s":"Oxford University Press","d":"14/11/2026","u":"https://academic.oup.com/edited-volume/61663/chapter/553397313"},
  "nok-britannica": {"t":"Nok culture (Britannica; search excerpt): first discovered in 1928 in the tin-mining village of Nok; the culture existed on the Benue Plateau of Nigeria from about 500 BCE to 200 CE; clay figurines of animals and people","s":"Encyclopaedia Britannica","d":"14/11/2026","u":"https://www.britannica.com/topic/Nok-culture"},
  "nok-breunig-2026": {"t":"Breunig and Franke, interview in Uni Report 2/2026, Goethe University Frankfurt (search excerpt, German original; not read in full): no large settlements, monumental architecture or central workshops found; a society of small farming villages; the link between Nok and later Ife is an unresolved research question","s":"Goethe University Frankfurt","d":"06/07/2026","u":"https://www.uni-frankfurt.de/en/newsroom/uni-report/ausgabe-2-2026/grosse-kunst-aber-keine-hochkultur"},
  "icom-redlist": {"t":"ICOM, Red List of African archaeological objects at risk (January 2000; search excerpt): objects cannot be understood once removed from their archaeological context; only professional excavation recovers their identity, date and location; Nok terracotta is listed","s":"International Council of Museums","d":"14/11/2026","u":"https://icom.museum/wp-content/uploads/2019/03/Red-List-Africa-English-and-French.pdf"},
  "intcal20": {"t":"Reimer et al., The IntCal20 Northern Hemisphere Radiocarbon Age Calibration Curve (0-55 cal kBP), Radiocarbon 2020 (search excerpt; not read in full): the Hallstatt plateau, ca. 800-400 BC, is a flat stretch of the curve where radiocarbon ages barely separate calendar dates","s":"Radiocarbon (Cambridge University Press)","d":"14/11/2026","u":"https://www.cambridge.org/core/journals/radiocarbon/article/intcal20-northern-hemisphere-radiocarbon-age-calibration-curve-055-cal-kbp/83257B63DC3AF9CFA6243F59D7503EFF"},
  "pnas-bantu-2022": {"t":"Bayesian phylogeographic analysis of the Bantu expansion, PNAS 2022 (search excerpt; not read in full): more than 500 Bantu languages; the homeland is around the Nigeria-Cameroon border; inception about 5,110 years BP (95% interval 4,640 to 5,770)","s":"PNAS","d":"14/11/2026","u":"https://www.pnas.org/doi/10.1073/pnas.2112853119"},
  "oxbib-bantu": {"t":"Bantu Expansion, Oxford Bibliographies in African Studies (search excerpt; not read in full): 440 to 680 Bantu languages depending on how language and dialect are distinguished; the ancestral proto-language diverged from its Niger-Congo ancestors about 4,000 to 5,000 years ago","s":"Oxford Bibliographies (Oxford University Press)","d":"14/11/2026","u":"https://academic.oup.com/reference/62328/reference-article/553804810"},
  "ehraf-jj": {"t":"Excavations at Jenne-Jeno, Hambarketolo and Kaniana, Inland Niger Delta, Mali: the 1981 season (S. K. McIntosh, ed., University of California Press, 1994), summary in eHRAF Archaeology (search excerpt; not read in full): occupation from 250 BC; phases from 250 BC to AD 1400; brick walls, pottery and burials; settlement hierarchy and long-distance trade, but no social stratification","s":"University of California Press (eHRAF Archaeology, Yale)","d":"14/11/2026","u":"https://ehrafarchaeology.yale.edu/document?id=fa75-003"},
  "penn-jj": {"t":"Penn Museum, Expedition magazine, Forgotten Tells of Mali (search excerpt; not read in full): Jenne-jeno founded by the 3rd century BC; about 12 hectares by about AD 50 and 33 hectares by AD 600 to 800; then enclosed by a 3.3 metre mud-brick wall","s":"Penn Museum","d":"14/11/2026","u":"https://www.penn.museum/sites/expedition/forgotten-tells-of-mali"},
  "mcintosh-rwe": {"t":"Jenne-Jeno, Archaeology of, Encyclopedia of Global Archaeology (Springer; search excerpt): the first indigenous city recognised south of the Sahara; no evidence yet for kings, a state apparatus or a hierarchical power structure; the type site for heterarchical (nonhierarchical) authority","s":"Springer Nature","d":"14/11/2026","u":"https://link.springer.com/rwe/10.1007/978-1-4419-0465-2_986"},
  "mcintosh-memoir": {"t":"Autobiographical essay by an excavator of Jenne-jeno, Intellectual Trajectories vol. 5 (Yale, 2024; search excerpt): occupation from 200 BCE to 1400 CE; no outsiders and no sign of long-distance trade with North Africa; no king or despotic apparatus; the author did not coin the term heterarchy, but the Middle Niger case became its case study","s":"Yale Emeritus, Intellectual Trajectories","d":"14/11/2026","u":"https://emeritus.yale.edu/system/files/IT-talks/mcintosh-intellectualtrajectory-2024-accessible.pdf"},
  "standen-jj": {"t":"Leyser, Standen, Wynne-Jones et al., Settlement, Landscape and Narrative (Oxford, 2019; search excerpt): Jenne-jeno as an urban cluster with no citadel or monumental centre; Susan McIntosh used heterarchy to explain the combination of craft specialisation and no hierarchy","s":"University of Oxford (ORA)","d":"14/11/2026","u":"https://ora.ox.ac.uk/objects/uuid:6dd8363a-7bb6-49c4-a773-b72eaca1d58d/files/m81d9e179b7fa3f517209d0636c159b93"},
  "griot-brit": {"t":"Griot (Britannica; search excerpt): West African troubadour-historian; the profession is hereditary; griots preserve genealogies, historical narratives and oral traditions","s":"Encyclopaedia Britannica","d":"14/11/2026","u":"https://www.britannica.com/art/griot"},
  "hale-griot": {"t":"Thomas Hale, From the Griot of Roots to the Roots of Griot, Oral Tradition 12(2), 2007 (search excerpt; not read in full): griots are born into the profession and act as genealogists, historians, advisers and spokespersons; the Maninka and Bamana term is jeli","s":"Oral Tradition journal","d":"14/11/2026","u":"https://journal.oraltradition.org/wp-content/uploads/files/articles/12ii/2_Hale.pdf"},
  "vansina-jstor": {"t":"Jan Vansina, Oral Tradition as History (University of Wisconsin Press, 1985), publisher's description on JSTOR: an oral tradition is a message based on earlier oral messages, at least a generation old, transmitted by word of mouth over time","s":"University of Wisconsin Press (JSTOR)","d":"14/11/2026","u":"https://www.jstor.org/stable/jj.36106057"},
